package ai.decisionos.aside;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.webkit.*;import android.location.*;import org.json.*;import java.net.*;import java.io.*;import java.time.*;import java.util.*;
/** Local-only scenario lab. External webpages never receive a native bridge. */
public final class ScenarioLabActivity extends Activity {
 WebView web; String goal; android.content.SharedPreferences prefs; JSONObject gps;
 @Override public void onCreate(Bundle b){super.onCreate(b);goal=getIntent().getStringExtra("goal_id");if(goal==null)goal="";if(goal.isEmpty()){try(GoalStore store=new GoalStore(this)){for(JSONObject g:store.goals())if(!GoalStore.fixture(g)&&g.optString("character").equals("grades")){goal=g.optString("id");break;}}}prefs=getSharedPreferences("scenario_lab",0);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);web.addJavascriptInterface(new Bridge(),"Lab");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest q){return true;}});android.widget.FrameLayout root=new android.widget.FrameLayout(this);root.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);root.requestApplyInsets();root.post(()->{if(Build.VERSION.SDK_INT>=30&&getWindow().getDecorView().getWindowInsetsController()!=null)getWindow().getDecorView().getWindowInsetsController().setSystemBarsAppearance(android.view.WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS,android.view.WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS);});web.loadUrl("file:///android_asset/scenario_lab/index.html");}
 void emit(String key,JSONObject data){runOnUiThread(()->{if(!isFinishing())web.evaluateJavascript("window.labResult("+JSONObject.quote(key)+","+data.toString()+")",null);});}
 JSONObject obj(String key,Object value){JSONObject j=new JSONObject();GoalStore.put(j,key,value);return j;}
 static String get(String url)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Mozilla/5.0 Nubi/0.6.21");c.setRequestProperty("Accept",url.contains("meal.hexa")?"application/json":"text/html");c.setRequestProperty("Origin","https://meal.hexa.pro");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1048576)throw new IOException("응답 크기 초과");}return out.toString("UTF-8");}}finally{c.disconnect();}}
 final class Bridge {
 @JavascriptInterface public void request(String key,String json){if(key.length()>40||json.length()>20000)return;runOnUiThread(()->handle(key,json));}
 }
 void handle(String key,String json){try{JSONObject j=new JSONObject(json);if(key.equals("practice_load")){File f=new File(getFilesDir(),"scenario-practice.py");if(!f.isFile()||f.length()>20000)throw new IOException("검증된 GPT 연습 과제 파일이 아직 없어요");emit(key,obj("code",new String(java.nio.file.Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8)));return;}if(key.equals("practice_submit")){File f=new File(getFilesDir(),"scenario-practice.py");File proof=new File(getFilesDir(),"scenario-practice-proof.json");if(!f.isFile()||!proof.isFile())throw new IOException("독립 검사 결과가 필요해요");JSONObject pv=new JSONObject(new String(java.nio.file.Files.readAllBytes(proof.toPath()),java.nio.charset.StandardCharsets.UTF_8));String hash=String.format("%064x",new java.math.BigInteger(1,java.security.MessageDigest.getInstance("SHA-256").digest(java.nio.file.Files.readAllBytes(f.toPath()))));if(!hash.equals(pv.optString("sha256"))||!pv.optBoolean("tests_passed"))throw new IOException("파일 해시 또는 독립 검사 불일치");JSONObject receipt=obj("environment","LOCAL_TEST_LMS");receipt.put("receipt_id","TEST-LMS-"+hash.substring(0,12));receipt.put("sha256",hash);receipt.put("submitted_at",Instant.now().toString());receipt.put("official_blackboard_submission",false);receipt.put("model",pv.optString("model"));prefs.edit().putString("practice_receipt",receipt.toString()).commit();emit(key,receipt);return;}if(key.equals("gps")){locate();return;}if(key.equals("load")){emit(key,new JSONObject(prefs.getString("simulation","{}")));return;}if(key.equals("save")){prefs.edit().putString("simulation",j.toString()).apply();emit(key,obj("saved",true));return;}if(key.equals("alarm")){long due=Instant.parse(j.getString("due")).toEpochMilli();String id;try(ScheduledWorkStore s=new ScheduledWorkStore(this)){id=s.create(goal,j.getString("title"),j.getString("prompt"),"reminder","",due,System.currentTimeMillis());}ScheduledWork.arm(this,id);emit(key,obj("id",id));return;}if(key.equals("meals")||key.equals("bus")){new Thread(()->{try{if(key.equals("meals")){LocalDate d=LocalDate.parse(j.getString("day"));String monday=d.minusDays(d.getDayOfWeek().getValue()-1).toString();JSONObject v=new JSONObject(get("https://meal.hexa.pro/v2/menu/"+monday));v.put("source","https://meal.hexa.pro/v2/menu/"+monday);emit(key,v);}else{String html=get("https://bus.hexa.pro/unist?lang=ko");java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?s)route-513.*?삼남.*?(\\d{2}:\\d{2}) 출발 예정").matcher(html);JSONObject v=obj("source","https://bus.hexa.pro/unist?lang=ko");v.put("fetched_at",Instant.now().toString());v.put("direction","삼남·울산역");if(!m.find())throw new IOException("513 울산역 방면 시각을 읽지 못했어요");v.put("departure_hm",m.group(1));emit(key,v);}}catch(Exception e){emit(key,obj("error",e.getClass().getSimpleName()+": "+e.getMessage()));}}).start();return;}emit(key,obj("error","지원하지 않는 요청"));}catch(Exception e){emit(key,obj("error",e.getClass().getSimpleName()+": "+e.getMessage()));}}
 void locate(){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},8252);return;}LocationManager lm=getSystemService(LocationManager.class);String p=lm.isProviderEnabled("network")?"network":lm.isProviderEnabled("gps")?"gps":null;if(p==null){emit("gps",obj("error","기기 위치 설정을 켜 주세요"));return;}CancellationSignal cancel=new CancellationSignal();boolean[] done={false};Handler h=new Handler(getMainLooper());h.postDelayed(()->{if(done[0])return;done[0]=true;cancel.cancel();emit("gps",obj("error","20초 안에 최근 위치를 얻지 못했어요. 실외에서 재시도해 주세요."));},20000);lm.getCurrentLocation(p,cancel,getMainExecutor(),l->{if(done[0])return;done[0]=true;if(!TravelLocation.usable(l,SystemClock.elapsedRealtimeNanos())){emit("gps",obj("error","최근 위치 없음 또는 오차 200m 초과"));return;}gps=new JSONObject();GoalStore.put(gps,"latitude",l.getLatitude());GoalStore.put(gps,"longitude",l.getLongitude());GoalStore.put(gps,"accuracy_m",l.getAccuracy());GoalStore.put(gps,"observed_at",Instant.ofEpochMilli(l.getTime()).toString());GoalStore.put(gps,"used_for_ulsan_simulation",false);emit("gps",gps);});}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==8252){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)locate();else emit("gps",obj("error","위치 권한이 허용되지 않았어요"));}}
 @Override protected void onDestroy(){web.removeJavascriptInterface("Lab");web.destroy();super.onDestroy();}
}
